-- Changelog-item voor de foutenlog-pagina (/instellingen/foutenlog).

insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-16','nieuw','Systeem','Foutenlog: zien wat er misgaat',
   'Beheerders vinden onder Bedrijfsinstellingen een nieuw Foutenlog: welke fout er optrad, wanneer, hoe vaak en wie het raakte. Dezelfde fout blijft één regel met een teller, zodat je in één blik ziet wat de meeste collega''s hindert. Klapt er iets, dan krijgt de gebruiker voortaan een nette melding in plaats van een lege pagina, en wordt de fout automatisch doorgegeven.');
